package com.bank.payeeac.service;

import com.bank.payeeac.trie.TrieNode;
import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

// Prefix walk plus subtree collection for autocomplete suggestions.
public class PayeeAutocompleteService {
    private static final Logger log = Logger.getLogger(PayeeAutocompleteService.class.getName());
    private final TrieNode root = new TrieNode();

    public void insert(String name) {
        TrieNode node = root;
        for (char c : name.toCharArray())
            node = node.children.computeIfAbsent(c, k -> new TrieNode());
        node.isWord = true;
    }

    public List<String> suggest(String prefix, int limit) {
        List<String> out = new ArrayList<>();
        TrieNode node = root;
        for (char c : prefix.toCharArray()) {        // walk to the prefix node
            node = node.children.get(c);
            if (node == null) {
                log.fine(() -> "No payee starts with " + prefix);
                return out;                          // nothing matches
            }
        }
        collect(node, new StringBuilder(prefix), out, limit); // gather subtree words
        log.info(() -> "Suggestions for " + prefix + " = " + out);
        return out;
    }

    private void collect(TrieNode node, StringBuilder cur, List<String> out, int limit) {
        if (out.size() >= limit) return;            // top-few limit reached
        if (node.isWord) out.add(cur.toString());   // a complete name under the prefix
        for (var e : node.children.entrySet()) {     // sorted → alphabetical order
            cur.append(e.getKey());
            collect(e.getValue(), cur, out, limit);
            cur.deleteCharAt(cur.length() - 1);     // backtrack the suffix
        }
    }
}
