package com.bank.payeeac;

import com.bank.payeeac.service.PayeeAutocompleteService;
import java.util.List;
import java.util.logging.Logger;

public class PayeeAutocompleteApplication {
    private static final Logger log = Logger.getLogger(PayeeAutocompleteApplication.class.getName());

    public static void main(String[] args) {
        PayeeAutocompleteService service = new PayeeAutocompleteService();
        service.insert("RAJESH");
        service.insert("RAJIV");
        service.insert("PRIYA");
        List<String> suggestions = service.suggest("RAJ", 5);
        log.info("Autocomplete for RAJ: " + suggestions);
    }
}
